using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using IdentityServer3.Core.Configuration;
using IdentityServer3.Core.Models;
using IdentityServer3.Core.Services;
using IdentityServer3.Core.Services.InMemory;
using IdentityServer3.EntityFramework;
using Microsoft.Owin;
using Microsoft.Owin.Security.Cookies;
using Owin;
using HealthConnect.Auth.Models;
using HealthConnect.Auth.Services;

[assembly: OwinStartup(typeof(HealthConnect.Auth.Startup))]

namespace HealthConnect.Auth
{
    public class Startup
    {
        public void Configuration(IAppBuilder app)
        {
            // Configure cookie authentication
            app.UseCookieAuthentication(new CookieAuthenticationOptions
            {
                AuthenticationType = "Cookies"
            });

            // Configure IdentityServer3 with Entity Framework
            var factory = new IdentityServerServiceFactory
            {
                ClientStore = new Registration<IClientStore>(resolver => 
                    new ClientStore(resolver.Resolve<AuthDbContext>())),
                ScopeStore = new Registration<IScopeStore>(resolver => 
                    new ScopeStore(resolver.Resolve<AuthDbContext>())),
                TokenHandleStore = new Registration<ITokenHandleStore>(resolver => 
                    new TokenHandleStore(resolver.Resolve<AuthDbContext>())),
                RefreshTokenStore = new Registration<IRefreshTokenStore>(resolver => 
                    new RefreshTokenStore(resolver.Resolve<AuthDbContext>())),
                ConsentStore = new Registration<IConsentStore>(resolver => 
                    new ConsentStore(resolver.Resolve<AuthDbContext>())),
                AuthorizationCodeStore = new Registration<IAuthorizationCodeStore>(resolver => 
                    new AuthorizationCodeStore(resolver.Resolve<AuthDbContext>())),
            };

            // User service - currently using in-memory, needs to integrate with AD/LDAP
            factory.UserService = new Registration<IUserService>(resolver => 
                new InMemoryUserService(Users.Get()));

            // Configure CORS - minimal for now
            app.UseCors(Microsoft.Owin.Cors.CorsOptions.AllowAll);

            // Setup IdentityServer options
            var options = new IdentityServerOptions
            {
                Factory = factory,
                SiteName = "HealthConnect Authorization Server",
                SigningCertificate = Certificate.Get(),
                RequireSsl = true,
                AuthenticationOptions = new AuthenticationOptions
                {
                    EnablePostSignOutAutoRedirect = true,
                    CookieOptions = new CookieOptions
                    {
                        SecureMode = CookieSecureMode.Always
                    }
                },
                Endpoints = new EndpointOptions
                {
                    EnableAuthorizeEndpoint = true,
                    EnableTokenEndpoint = true,
                    EnableUserInfoEndpoint = true,
                    EnableDiscoveryEndpoint = true,
                    EnableEndSessionEndpoint = true,
                    EnableCheckSessionEndpoint = true,
                    EnableTokenRevocationEndpoint = true
                },
                LoggingOptions = new LoggingOptions
                {
                    EnableHttpLogging = true,
                    EnableKatanaLogging = true,
                    EnableWebApiDiagnostics = true
                },
                EventsOptions = new EventsOptions
                {
                    RaiseSuccessEvents = true,
                    RaiseFailureEvents = true,
                    RaiseErrorEvents = true
                },
                // Missing: PKCE support, proper MFA, consent logging
                // Missing: Token rotation, refresh token families
                // Missing: LDAP/AD integration
            };

            app.UseIdentityServer(options);
        }
    }

    // Temporary in-memory users - TO BE REPLACED WITH AD/LDAP
    public static class Users
    {
        public static List<InMemoryUser> Get()
        {
            return new List<InMemoryUser>
            {
                new InMemoryUser
                {
                    Username = "doctorjones",
                    Password = "TempPass123!", // Should come from AD
                    Subject = "1",
                    Claims = new[]
                    {
                        new System.Security.Claims.Claim("name", "Dr. Michael Jones"),
                        new System.Security.Claims.Claim("email", "mjones@healthconnect.com"),
                        new System.Security.Claims.Claim("role", "physician"),
                        new System.Security.Claims.Claim("department", "cardiology")
                    }
                },
                new InMemoryUser
                {
                    Username = "nursewilson",
                    Password = "TempPass456!",
                    Subject = "2",
                    Claims = new[]
                    {
                        new System.Security.Claims.Claim("name", "Sarah Wilson"),
                        new System.Security.Claims.Claim("email", "swilson@healthconnect.com"),
                        new System.Security.Claims.Claim("role", "nurse"),
                        new System.Security.Claims.Claim("department", "emergency")
                    }
                }
            };
        }
    }

    // Temporary certificate - should be from secure store
    public static class Certificate
    {
        public static System.Security.Cryptography.X509Certificates.X509Certificate2 Get()
        {
            // In production, this should load from Azure Key Vault or Windows Certificate Store
            var assembly = typeof(Startup).Assembly;
            using (var stream = assembly.GetManifestResourceStream("HealthConnect.Auth.idsrv3test.pfx"))
            {
                return new System.Security.Cryptography.X509Certificates.X509Certificate2(
                    ReadStream(stream), "idsrv3test");
            }
        }

        private static byte[] ReadStream(System.IO.Stream input)
        {
            var buffer = new byte[16 * 1024];
            using (var ms = new System.IO.MemoryStream())
            {
                int read;
                while ((read = input.Read(buffer, 0, buffer.Length)) > 0)
                {
                    ms.Write(buffer, 0, read);
                }
                return ms.ToArray();
            }
        }
    }
}
