using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace HealthConnect.Auth.Data
{
    public class AuthDbContext : DbContext
    {
        public AuthDbContext(DbContextOptions<AuthDbContext> options)
            : base(options)
        {
        }

        public DbSet<Client> Clients { get; set; }
        public DbSet<ClientSecret> ClientSecrets { get; set; }
        public DbSet<ClientRedirectUri> ClientRedirectUris { get; set; }
        public DbSet<ClientPostLogoutRedirectUri> ClientPostLogoutRedirectUris { get; set; }
        public DbSet<ClientScope> ClientScopes { get; set; }
        public DbSet<ClientGrantType> ClientGrantTypes { get; set; }
        public DbSet<ClientCorsOrigin> ClientCorsOrigins { get; set; }
        
        public DbSet<Token> Tokens { get; set; }
        public DbSet<RefreshToken> RefreshTokens { get; set; }
        public DbSet<AuthorizationCode> AuthorizationCodes { get; set; }
        
        public DbSet<Consent> Consents { get; set; }
        public DbSet<AuditLog> AuditLogs { get; set; }
        
        // Missing: MFA configurations, token rotation tracking, refresh token families

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            // Client configuration
            modelBuilder.Entity<Client>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.ClientId).IsRequired().HasMaxLength(200);
                entity.Property(e => e.ClientName).HasMaxLength(200);
                entity.Property(e => e.ClientUri).HasMaxLength(2000);
                entity.HasIndex(e => e.ClientId).IsUnique();
                
                // Relationships
                entity.HasMany(e => e.ClientSecrets)
                    .WithOne(e => e.Client)
                    .HasForeignKey(e => e.ClientId)
                    .OnDelete(DeleteBehavior.Cascade);
                
                entity.HasMany(e => e.RedirectUris)
                    .WithOne(e => e.Client)
                    .HasForeignKey(e => e.ClientId)
                    .OnDelete(DeleteBehavior.Cascade);
                
                entity.HasMany(e => e.AllowedScopes)
                    .WithOne(e => e.Client)
                    .HasForeignKey(e => e.ClientId)
                    .OnDelete(DeleteBehavior.Cascade);
                
                entity.HasMany(e => e.AllowedGrantTypes)
                    .WithOne(e => e.Client)
                    .HasForeignKey(e => e.ClientId)
                    .OnDelete(DeleteBehavior.Cascade);
            });

            modelBuilder.Entity<ClientSecret>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Value).IsRequired().HasMaxLength(2000);
                entity.Property(e => e.Type).HasMaxLength(250);
                entity.Property(e => e.Description).HasMaxLength(2000);
            });

            modelBuilder.Entity<ClientRedirectUri>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Uri).IsRequired().HasMaxLength(2000);
            });

            modelBuilder.Entity<ClientScope>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Scope).IsRequired().HasMaxLength(200);
            });

            modelBuilder.Entity<ClientGrantType>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.GrantType).IsRequired().HasMaxLength(250);
            });

            // Token storage
            modelBuilder.Entity<Token>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.SubjectId).HasMaxLength(200);
                entity.Property(e => e.ClientId).IsRequired().HasMaxLength(200);
                entity.Property(e => e.JsonCode).IsRequired();
                entity.Property(e => e.Type).IsRequired().HasMaxLength(50);
                
                entity.HasIndex(e => e.SubjectId);
                entity.HasIndex(e => e.ClientId);
                entity.HasIndex(e => e.Expiry);
                
                // Missing: Token rotation tracking, family identifier
            });

            modelBuilder.Entity<RefreshToken>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.SubjectId).HasMaxLength(200);
                entity.Property(e => e.ClientId).IsRequired().HasMaxLength(200);
                entity.Property(e => e.JsonCode).IsRequired();
                
                entity.HasIndex(e => e.SubjectId);
                entity.HasIndex(e => e.ClientId);
                entity.HasIndex(e => e.Expiry);
                
                // Missing: Refresh token family tracking
            });

            // Consent management (basic - needs GDPR enhancements)
            modelBuilder.Entity<Consent>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Subject).IsRequired().HasMaxLength(200);
                entity.Property(e => e.ClientId).IsRequired().HasMaxLength(200);
                entity.Property(e => e.Scopes).IsRequired().HasMaxLength(2000);
                
                entity.HasIndex(e => new { e.Subject, e.ClientId });
                
                // Missing: Consent versioning, purpose specification, withdrawal tracking
            });

            // Audit logging (basic - needs HIPAA enhancements)
            modelBuilder.Entity<AuditLog>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.Property(e => e.Event).IsRequired().HasMaxLength(100);
                entity.Property(e => e.Subject).HasMaxLength(200);
                entity.Property(e => e.ClientId).HasMaxLength(200);
                entity.Property(e => e.IpAddress).HasMaxLength(45);
                entity.Property(e => e.Details).HasMaxLength(4000);
                
                entity.HasIndex(e => e.Timestamp);
                entity.HasIndex(e => e.Event);
                entity.HasIndex(e => e.Subject);
                
                // Missing: HIPAA-specific fields (purpose of use, patient ID correlation)
            });
        }
    }

    // Entity classes
    public class Client
    {
        public int Id { get; set; }
        public string ClientId { get; set; } = null!;
        public bool Enabled { get; set; } = true;
        public string ClientName { get; set; } = null!;
        public string ClientUri { get; set; } = null!;
        public bool RequireConsent { get; set; } = true;
        public bool AllowRememberConsent { get; set; } = true;
        public int AccessTokenLifetime { get; set; } = 3600; // 1 hour
        public int IdentityTokenLifetime { get; set; } = 300; // 5 minutes
        public int AbsoluteRefreshTokenLifetime { get; set; } = 2592000; // 30 days
        public int SlidingRefreshTokenLifetime { get; set; } = 1296000; // 15 days
        public bool UpdateAccessTokenClaimsOnRefresh { get; set; }
        public bool IncludeJwtId { get; set; }
        public bool AlwaysSendClientClaims { get; set; }
        public bool PrefixClientClaims { get; set; } = true;
        
        // Missing: PKCE configuration, MFA requirements per client
        
        // Navigation properties
        public ICollection<ClientSecret> ClientSecrets { get; set; } = new List<ClientSecret>();
        public ICollection<ClientRedirectUri> RedirectUris { get; set; } = new List<ClientRedirectUri>();
        public ICollection<ClientPostLogoutRedirectUri> PostLogoutRedirectUris { get; set; } = new List<ClientPostLogoutRedirectUri>();
        public ICollection<ClientScope> AllowedScopes { get; set; } = new List<ClientScope>();
        public ICollection<ClientGrantType> AllowedGrantTypes { get; set; } = new List<ClientGrantType>();
        public ICollection<ClientCorsOrigin> AllowedCorsOrigins { get; set; } = new List<ClientCorsOrigin>();
    }

    public class ClientSecret
    {
        public int Id { get; set; }
        public string Value { get; set; } = null!;
        public string Type { get; set; } = "SharedSecret";
        public string? Description { get; set; }
        public DateTime? Expiration { get; set; }
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class ClientRedirectUri
    {
        public int Id { get; set; }
        public string Uri { get; set; } = null!;
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class ClientPostLogoutRedirectUri
    {
        public int Id { get; set; }
        public string Uri { get; set; } = null!;
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class ClientScope
    {
        public int Id { get; set; }
        public string Scope { get; set; } = null!;
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class ClientGrantType
    {
        public int Id { get; set; }
        public string GrantType { get; set; } = null!;
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class ClientCorsOrigin
    {
        public int Id { get; set; }
        public string Origin { get; set; } = null!;
        
        public int ClientId { get; set; }
        public Client Client { get; set; } = null!;
    }

    public class Token
    {
        public int Id { get; set; }
        public string? SubjectId { get; set; }
        public string ClientId { get; set; } = null!;
        public string JsonCode { get; set; } = null!;
        public DateTime Expiry { get; set; }
        public string Type { get; set; } = null!; // "access_token", "identity_token"
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        
        // Missing: Token family ID for rotation
    }

    public class RefreshToken
    {
        public int Id { get; set; }
        public string? SubjectId { get; set; }
        public string ClientId { get; set; } = null!;
        public string JsonCode { get; set; } = null!;
        public DateTime Expiry { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        
        // Missing: Family identifier, rotation count
    }

    public class AuthorizationCode
    {
        public int Id { get; set; }
        public string? SubjectId { get; set; }
        public string ClientId { get; set; } = null!;
        public string JsonCode { get; set; } = null!;
        public DateTime Expiry { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        
        // Missing: PKCE code challenge and method
    }

    public class Consent
    {
        public int Id { get; set; }
        public string Subject { get; set; } = null!;
        public string ClientId { get; set; } = null!;
        public string Scopes { get; set; } = null!; // JSON array of scopes
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime? ExpiresAt { get; set; }
        
        // Missing: Purpose of consent, version, withdrawal timestamp
    }

    public class AuditLog
    {
        public int Id { get; set; }
        public string Event { get; set; } = null!; // "TokenIssued", "ConsentGranted", "LoginFailed"
        public string? Subject { get; set; }
        public string? ClientId { get; set; }
        public string? IpAddress { get; set; }
        public string? Details { get; set; } // JSON details
        public DateTime Timestamp { get; set; } = DateTime.UtcNow;
        
        // Missing: HIPAA-specific fields
    }
