// game_loop.c - RetroArcadeRacer v1.2.4
// Current timing implementation using Sleep(16)
// Known issues: Physics jitter on Win11, occasional 500ms lock

#include <windows.h>
#include <stdint.h>
#include <stdio.h>

#include "game_state.h"
#include "physics_system.h"
#include "render_system.h"

#define TARGET_FPS 60
#define MS_PER_FRAME (1000 / TARGET_FPS)  // ~16ms

static LARGE_INTEGER perf_freq;
static BOOL perf_freq_initialized = FALSE;

static double get_current_time_seconds(void) {
    LARGE_INTEGER counter;
    if (!perf_freq_initialized) {
        QueryPerformanceFrequency(&perf_freq);
        perf_freq_initialized = TRUE;
    }
    QueryPerformanceCounter(&counter);
    return (double)counter.QuadPart / (double)perf_freq.QuadPart;
}

typedef struct {
    double last_time;
    double accumulator;
    double frame_time;
    uint32_t frame_count;
    double fps_update_time;
    double min_delta;
    double max_delta;
} TimingData;

void game_loop_run(HWND hwnd, ID3D11Device* device, ID3D11DeviceContext* context) {
    GameState* game_state = game_state_create();
    if (!game_state) {
        MessageBoxA(hwnd, "Failed to create game state", "Error", MB_ICONERROR);
        return;
    }

    // Initialize with 100 entities (cars, obstacles, particles)
    for (int i = 0; i < 100; i++) {
        game_state_add_entity(game_state, ENTITY_TYPE_CAR);
    }

    TimingData timing = {0};
    timing.last_time = get_current_time_seconds();
    timing.fps_update_time = timing.last_time;
    timing.min_delta = 1.0;  // Start high
    timing.max_delta = 0.0;

    const double fixed_dt = 1.0 / 60.0;  // 60Hz physics

    MSG msg = {0};
    BOOL running = TRUE;

    while (running) {
        // Process Windows messages
        while (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) {
                running = FALSE;
                break;
            }
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }

        // Calculate delta time (variable timestep - PROBLEMATIC)
        double current_time = get_current_time_seconds();
        double delta_time = current_time - timing.last_time;
        timing.last_time = current_time;

        // Track min/max delta for debugging
        if (delta_time < timing.min_delta && delta_time > 0.0) {
            timing.min_delta = delta_time;
        }
        if (delta_time > timing.max_delta) {
            timing.max_delta = delta_time;
            if (delta_time > 0.1) {  // Log spikes > 100ms
                char buf[256];
                sprintf(buf, "Frame spike: %.3f ms\n", delta_time * 1000.0);
                OutputDebugStringA(buf);
            }
        }

        // PROBLEM: Variable delta time causes physics jitter
        // Physics expects fixed timestep but gets variable
        physics_system_update(game_state, delta_time);

        // Render
        render_system_begin_frame(device, context);
        render_system_draw(game_state, device, context);
        render_system_end_frame(device, context);

        // PROBLEM: Sleep(16) has poor resolution on Windows
        // Can sleep longer than requested, especially on Win11
        // Causes frame rate drops and physics issues
        Sleep(MS_PER_FRAME);

        // FPS calculation
        timing.frame_count++;
        double now = get_current_time_seconds();
        if (now - timing.fps_update_time >= 1.0) {
            double fps = timing.frame_count / (now - timing.fps_update_time);
            char title[128];
            sprintf(title, "RetroArcadeRacer - FPS: %.1f (min: %.2fms, max: %.2fms)", 
                    fps, timing.min_delta * 1000.0, timing.max_delta * 1000.0);
            SetWindowTextA(hwnd, title);

            timing.frame_count = 0;
            timing.fps_update_time = now;
            timing.min_delta = 1.0;
            timing.max_delta = 0.0;
        }
    }

    game_state_destroy(game_state);
}

// Helper function called from WinMain
void run_game(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    // Window creation and D3D11 setup omitted for brevity
    // ...

    // Run the game loop
    game_loop_run(hwnd, d3d_device, d3d_context);

    // Cleanup
    // ...
}

