    float angular_velocity;
    float width, height; // Bounding box
    EntityType type;
    int is_active;
    void* data; // Type-specific data
} Entity;

typedef struct {
    Entity entities[MAX_ENTITIES];
    int entity_count;
    float track_scroll_offset;
    int player_score;
    int game_time_ms;
} GameState;

